def semver_sort(versions):
    def parse(v):
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        if pre is None:
            pre_ids = None
        else:
            pre_ids = pre.split('.')
        return (major, minor, patch, pre_ids)

    def pre_key(pre_ids):
        if pre_ids is None:
            return (1,)  # no pre-release sorts after
        parts = []
        for ident in pre_ids:
            if ident.isdigit():
                parts.append((0, int(ident)))
            else:
                parts.append((1, ident))
        return (0, len(parts), tuple(parts))

    def key(v):
        major, minor, patch, pre_ids = parse(v)
        return (major, minor, patch, pre_key(pre_ids))

    return sorted(versions, key=key)

